   "pre_process_code": "import json
try:
    b = config.get('body')
    if isinstance(b, dict):
        outcome = vars.get('close_outcome') or 'not_reached'
        reason = vars.get('close_reason') or 'unclear'
        tr = vars.get('transfer_reason') or ''
        pc = int(vars.get('promise_count') or 0)
        if tr:
            outcome, reason = 'transferred', tr
        elif pc > 0:
            outcome, reason = 'promise', ''
        elif outcome == 'no_promise':
            ids = json.loads(vars.get('product_ids_json') or '[]')
            notes = json.loads(vars.get('notes_json') or '[]')
            nmap = dict()
            for item in notes:
                if isinstance(item, list) and len(item) == 2 and item[0] not in nmap:
                    nmap[item[0]] = item[1]
