      "code": {"type": "string", "default": "import datetime
import json
import re

WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now: ' + s)

def parse_holidays(values):
    out = set()
    for v in values or []:
        try:
            out.add(datetime.date.fromisoformat(str(v)[:10]))
        except ValueError:
            pass
    return out

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays, include_today=False):
    if include_today and is_business_day(d, holidays):
        return d
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

def add_business_days(d, n, holidays):
    for _ in range(int(n)):
        d = next_business_day(d, holidays)
    return d

def week_monday(d):
    return d - datetime.timedelta(days=d.weekday())

def last_business_day_of_week(d, holidays):
    day = week_monday(d) + datetime.timedelta(days=4)
    while day >= week_monday(d):
        if is_business_day(day, holidays):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken_date(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

def money(amount):
    v = round(float(amount), 2)
    return '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = dict()
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit():
                if field:
                    rows.setdefault(int(idx), dict())[field] = value
                else:
                    rows[int(idx)] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

BANDS = [(1, 7, 12, 1, 'early'), (8, 45, 7, 2, 'late')]
try:
    now = parse_now(vars.get('now'))
    hol = parse_holidays(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    today = now.date()
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    week_end = last_business_day_of_week(today, hol)
    if week_end is None or week_end <= today:
        week_end = last_business_day_of_week(today + datetime.timedelta(days=7), hol)
    lines, facts, offers, states, ids = [], [], [], [], []
    for n, it in enumerate(items, 1):
        days = int(float(it.get('days_late') or 0))
        band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])
        deadline = add_business_days(today, band[2], hol)
        a1 = min(week_end, deadline) if week_end else deadline
        typ = str(it.get('type') or '')
        if typ == 'credit_card':
            label = 'credit card ending ' + str(it.get('card_last4') or '')
            floor = it.get('minimum_payment')
        elif typ == 'car_loan':
            label = 'car loan'
            floor = it.get('instalment_amount')
        else:
            label = 'personal loan'
            floor = it.get('instalment_amount')
        full = float(it.get('past_due') or 0)
        floor = float(floor) if floor not in (None, '') else full
        pid = str(it.get('product_id') or '')
        ids.append(pid)
        states.append('Your ' + label + ' is ' + money(full) + ' past due, ' + str(days) + ' days late.')
        lines.append(str(n) + '. ' + label + ' (product_id ' + pid + '): past due ' + money(full) + ', ' + str(days) + ' days late, band ' + band[4] + '. Floor (lowest amount you may record): ' + money(floor) + '. Deadline (latest date): ' + spoken_date(deadline) + ' (' + deadline.isoformat() + '). Persuasion attempts allowed: ' + str(band[3]) + '. Attempt 1 date: ' + spoken_date(a1) + ' (' + a1.isoformat() + ').' + (' Attempt 2: the floor on the deadline.' if band[3] > 1 else ' No attempt 2.'))
        offers.append('- ' + label + ', floor offer: "I can record ' + money(floor) + ' for your ' + label + '. The rest stays overdue."')
        offers.append('- ' + label + ', attempt 1 (full amount): "Could you pay ' + money(full) + ' for your ' + label + ' on ' + spoken_date(a1) + '?"')
        offers.append('- ' + label + ', attempt 1 (after the full amount was too much): "Could you pay ' + money(floor) + ' for your ' + label + ' on ' + spoken_date(a1) + '? The rest stays overdue."')
        if band[3] > 1:
            offers.append('- ' + label + ', attempt 2: "Could you pay ' + money(floor) + ' for your ' + label + ' on ' + spoken_date(deadline) + '? The rest stays overdue."')
        offers.append('- ' + label + ', date after the deadline: "The latest date I can record for your ' + label + ' is ' + spoken_date(deadline) + '."')
        facts.append(dict(product_id=pid, label=label, past_due=full, floor=floor, days_late=days, deadline=deadline.isoformat(), attempts=band[3], attempt1=a1.isoformat()))
    table = []
    for i in range(0, 22):
        d = today + datetime.timedelta(days=i)
        wk = (d - week_monday(today)).days // 7
        rel = 'this ' + WEEKDAYS[d.weekday()].title() if wk == 0 else ('next ' + WEEKDAYS[d.weekday()].title() if wk == 1 else '')
        bd = is_business_day(d, hol)
        okfor = [f['label'] for f in facts if bd and d.isoformat() <= f['deadline']]
        note = 'business day' if bd else ('holiday' if d in hol else 'weekend') + ', next business day ' + spoken_date(next_business_day(d, hol)) + ' (' + next_business_day(d, hol).isoformat() + ')'
        table.append('  ' + d.isoformat() + ' ' + spoken_date(d) + (' = ' + rel if rel else '') + ': ' + note + ('; allowed for: ' + ', '.join(okfor) if okfor else '; allowed for: none'))
    multi = len(facts) > 1
    vars['debt_statement'] = 'I am calling from the collections team about a late payment. ' + ' '.join(states)
    vars['first_ask'] = 'Can you make all of these payments today?' if multi else 'Can you make this payment today?'
    vars['facts_text'] = ('Today is ' + spoken_date(today) + ' (' + today.isoformat() + ').\nProducts in order:\n' + '\n'.join(lines) +
                          '\nDate table (use it, never compute dates yourself; this X = current week, next X = following calendar week):\n' + '\n'.join(table) +
                          '\nSay these sentences exactly when they apply:\n' + '\n'.join(offers) +
                          '\n- After a recorded promise: "You will receive a text message confirming this promise."')
    vars['facts_json'] = json.dumps(facts)
    vars['product_ids_json'] = json.dumps(ids)
    vars['product_count'] = str(len(facts))
    vars['facts_state'] = 'ok' if facts else 'empty'
    vars['close_outcome'] = 'no_promise'
    vars['close_reason'] = 'refused'
except Exception:
    vars['facts_text'] = 'The account details could not be read.'
    vars['debt_statement'] = ''
    vars['first_ask'] = 'Can you make this payment today?'
    vars['facts_json'] = '[]'
