     "pre_process_code": "import datetime
import re
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
try:
    b = config.get('body')
    if isinstance(b, dict):
        f = str(b.get('field') or '')
        a = str(b.get('answer') or '').strip()
        if f == 'phone_last4':
            digits = re.sub(r'\D', '', a)
            b['answer'] = digits[-4:] if len(digits) >= 4 else digits
        elif f == 'date_of_birth':
            s = a.lower()
            out = None
            m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
            if m:
                out = (int(m.group(1)), int(m.group(2)), int(m.group(3)))
            if out is None:
                m = re.search(r'\b(\d{1,2})[./\s-]+(\d{1,2})[./\s-]+(\d{4})\b', s)
                if m:
                    out = (int(m.group(3)), int(m.group(2)), int(m.group(1)))
            if out is None:
                ym = re.search(r'\b(\d{4})\b', s)
                for i, name in enumerate(MONTHS):
                    if re.search(r'\b' + name[:3] + r'[a-z]*\b', s) and ym:
                        dm = re.search(r'\b(\d{1,2})(st|nd|rd|th)?\b', s.replace(ym.group(1), ' '))
                        if dm:
                            out = (int(ym.group(1)), i + 1, int(dm.group(1)))
                        break
            if out is not None:
                try:
                    b['answer'] = datetime.date(out[0], out[1], out[2]).isoformat()
                except ValueError:
                    b['answer'] = '%04d-%02d-%02d' % out
except Exception:
    pass
