            outcome, reason = 'promise', ''
        elif outcome == 'no_promise':
            ids = json.loads(vars.get('product_ids_json') or '[]')
            notes = json.loads(vars.get('notes_json') or '[]')
            nmap = dict()
            for item in notes:
                if isinstance(item, list) and len(item) == 2 and item[0] not in nmap:
